package dev.aura.player;

import android.content.Context;import android.graphics.*;import android.text.Layout;

/** Only the active line redraws; text/layout are reused while the sung portion advances. */
final class KaraokeLineView extends androidx.appcompat.widget.AppCompatTextView {
    private final Path prefix=new Path(),glyph=new Path();private Layout cachedLayout;private int cachedComplete=-1,cachedNext=-1;private KaraokeTiming.Progress progress=new KaraokeTiming.Progress(0,0,0);private int accent;private boolean enabled;
    KaraokeLineView(Context context){super(context);setIncludeFontPadding(false);setLineSpacing(Ui.dp(context,8),1);}
    void highlight(KaraokeTiming.Progress value,boolean on,int color){if(enabled==on&&accent==color&&progress.equals(value))return;progress=value;enabled=on;accent=color;invalidate();}
    boolean hitsText(float x,float y){Layout layout=getLayout();if(layout==null||length()==0)return false;x-=getCompoundPaddingLeft()-getScrollX();y-=getExtendedPaddingTop()-getScrollY();if(y<0||y>=layout.getHeight())return false;int line=layout.getLineForVertical((int)y);android.graphics.Paint.FontMetrics metrics=getPaint().getFontMetrics();int baseline=layout.getLineBaseline(line);if(y<baseline+metrics.ascent||y>baseline+metrics.descent)return false;int offset=layout.getOffsetForHorizontal(line,x);for(int candidate:new int[]{offset,offset>0?Character.offsetByCodePoints(getText(),offset,-1):-1}){if(candidate<layout.getLineStart(line)||candidate>=layout.getLineEnd(line)||candidate>=length())continue;if(Character.isLowSurrogate(getText().charAt(candidate))&&candidate>0)candidate--;int code=Character.codePointAt(getText(),candidate);if(Character.isWhitespace(code)||Character.isISOControl(code))continue;int end=candidate+Character.charCount(code);float left=layout.getPrimaryHorizontal(candidate),right=layout.getLineForOffset(end)==line?layout.getPrimaryHorizontal(end):layout.getLineRight(line);if(x>=Math.min(left,right)&&x<=Math.max(left,right))return true;}return false;}
    @Override public boolean onTouchEvent(android.view.MotionEvent event){int action=event.getActionMasked();if(action==android.view.MotionEvent.ACTION_DOWN&&!hitsText(event.getX(),event.getY()))return false;if(action==android.view.MotionEvent.ACTION_UP&&!hitsText(event.getX(),event.getY())){var cancel=android.view.MotionEvent.obtain(event);cancel.setAction(android.view.MotionEvent.ACTION_CANCEL);super.onTouchEvent(cancel);cancel.recycle();return true;}return super.onTouchEvent(event);}
    @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);Layout layout=getLayout();if(!enabled||layout==null)return;int saved=canvas.save();canvas.translate(getCompoundPaddingLeft()-getScrollX(),getExtendedPaddingTop()-getScrollY());if(cachedLayout!=layout||cachedComplete!=progress.complete()||cachedNext!=progress.next()){cachedLayout=layout;cachedComplete=progress.complete();cachedNext=progress.next();prefix.reset();glyph.reset();if(cachedComplete>0)layout.getSelectionPath(0,Math.min(length(),cachedComplete),prefix);if(cachedNext>cachedComplete)layout.getSelectionPath(cachedComplete,Math.min(length(),cachedNext),glyph);}int color=getPaint().getColor();getPaint().setColor(accent);if(progress.complete()>0){int clip=canvas.save();canvas.clipPath(prefix);layout.draw(canvas);canvas.restoreToCount(clip);}if(progress.next()>progress.complete()&&progress.fraction()>0){int start=progress.complete(),stop=Math.min(length(),progress.next()),line=layout.getLineForOffset(start);float from=layout.getPrimaryHorizontal(start),to=layout.getLineForOffset(stop)==line?layout.getPrimaryHorizontal(stop):layout.isRtlCharAt(start)?layout.getLineLeft(line):layout.getLineRight(line);float amount=Math.abs(to-from)*progress.fraction();boolean rtl=layout.isRtlCharAt(start);float left=rtl?Math.max(from,to)-amount:Math.min(from,to),right=rtl?Math.max(from,to):Math.min(from,to)+amount;int clip=canvas.save();canvas.clipPath(glyph);canvas.clipRect(left,layout.getLineTop(line),right,layout.getLineBottom(line));layout.draw(canvas);canvas.restoreToCount(clip);}getPaint().setColor(color);canvas.restoreToCount(saved);}
}
